import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from '@posthog/lemon-ui'

import { integrationsLogic } from 'lib/integrations/integrationsLogic'
import { teamLogic } from 'scenes/teamLogic'

import type { IntegrationType } from '~/types'

import { slackAppSettingsPersonalPartialUpdate, slackAppSettingsRetrieve } from '../generated/api'
import type { PatchedSlackAppPersonalSettingsUpdateApi, SlackAppSettingsApi } from '../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface slackAppSettingsLogicValues {
    integrationsLoading: boolean // integrationsLogic
    slackIntegrations: IntegrationType[] | undefined // integrationsLogic
    currentTeamId: number | null // teamLogic
    pickedIntegrationId: number | null
    selectedIntegrationId: number | null
    settings: SlackAppSettingsApi | null
    settingsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface slackAppSettingsLogicActions {
    loadIntegrationsSuccess: (
        integrations: IntegrationType[],
        payload?: any
    ) => {
        integrations: IntegrationType[]
        payload?: any
    } // integrationsLogic
    loadSettings: (_: void) => void
    loadSettingsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSettingsSuccess: (
        settings: SlackAppSettingsApi | null,
        payload?: void
    ) => {
        settings: SlackAppSettingsApi | null
        payload?: void
    }
    selectIntegration: (integrationId: number) => {
        integrationId: number
    }
    updatePersonalSettings: (
        change: PatchedSlackAppPersonalSettingsUpdateApi
    ) => PatchedSlackAppPersonalSettingsUpdateApi
    updatePersonalSettingsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    updatePersonalSettingsSuccess: (
        settings: SlackAppSettingsApi | null,
        payload?: PatchedSlackAppPersonalSettingsUpdateApi
    ) => {
        settings: SlackAppSettingsApi | null
        payload?: PatchedSlackAppPersonalSettingsUpdateApi
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface slackAppSettingsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        selectedIntegrationId: (
            pickedIntegrationId: number | null,
            slackIntegrations: IntegrationType[] | undefined
        ) => number | null
    }
}

export type slackAppSettingsLogicType = MakeLogicType<
    slackAppSettingsLogicValues,
    slackAppSettingsLogicActions,
    Record<string, any>,
    slackAppSettingsLogicMeta
>

export const slackAppSettingsLogic = kea<slackAppSettingsLogicType>([
    path(['products', 'slack_app', 'frontend', 'settings', 'slackAppSettingsLogic']),
    connect(() => ({
        values: [integrationsLogic, ['slackIntegrations', 'integrationsLoading'], teamLogic, ['currentTeamId']],
        actions: [integrationsLogic, ['loadIntegrationsSuccess']],
    })),
    actions({
        selectIntegration: (integrationId: number) => ({ integrationId }),
    }),
    reducers({
        pickedIntegrationId: [
            null as number | null,
            {
                selectIntegration: (_, { integrationId }) => integrationId,
            },
        ],
        // Another workspace's settings must not stay on screen, or stay editable, while the new ones load.
        settings: {
            selectIntegration: () => null,
        },
    }),
    selectors({
        selectedIntegrationId: [
            (s) => [s.pickedIntegrationId, s.slackIntegrations],
            (pickedIntegrationId: number | null, slackIntegrations: IntegrationType[] | undefined): number | null =>
                pickedIntegrationId ?? slackIntegrations?.[0]?.id ?? null,
        ],
    }),
    loaders(({ values }) => ({
        settings: [
            null as SlackAppSettingsApi | null,
            {
                loadSettings: async (_: void, breakpoint) => {
                    if (values.selectedIntegrationId === null) {
                        return null
                    }
                    const response = await slackAppSettingsRetrieve(
                        String(values.currentTeamId),
                        String(values.selectedIntegrationId)
                    )
                    // A later load, after a workspace switch, replaces this response.
                    breakpoint()
                    return response
                },
                updatePersonalSettings: async (change: PatchedSlackAppPersonalSettingsUpdateApi) => {
                    const integrationId = values.selectedIntegrationId
                    if (integrationId === null) {
                        return values.settings
                    }
                    try {
                        const response = await slackAppSettingsPersonalPartialUpdate(
                            String(values.currentTeamId),
                            String(integrationId),
                            change
                        )
                        return integrationId === values.selectedIntegrationId ? response : values.settings
                    } catch (error: any) {
                        lemonToast.error(error?.detail ?? "Couldn't save your Slack settings. Try again.")
                        return values.settings
                    }
                },
            },
        ],
    })),
    listeners(({ actions }) => ({
        selectIntegration: () => actions.loadSettings(),
        loadIntegrationsSuccess: () => actions.loadSettings(),
    })),
    afterMount(({ actions, values }) => {
        if (values.slackIntegrations !== undefined) {
            actions.loadSettings()
        }
    }),
])
